#include "stdlib/math/base/special/factorialln.h"
#include "stdlib/constants/float64/nan.h"
#include "stdlib/math/base/assert/is_negative_integer.h"
#include "stdlib/math/base/special/gamma1pm1.h"
#include "stdlib/math/base/special/gammaln.h"
#include "stdlib/math/base/special/log1p.h"

/**
* Evaluates the natural logarithm of the factorial of `x`.
*
* ## Method
*
* The function evaluates `\ln \Gamma(x+1)`. For `-1 < x < 1`, forming `x+1` in double precision rounds away the low-order bits of `x` (all of them for `|x| < 2^{-53}`), so the function instead evaluates
*
* ```tex
* \ln \Gamma(x+1) = \operatorname{log1p}\left( \Gamma(x+1) - 1 \right)
* ```
*
* where `\Gamma(x+1) - 1` is computed directly from `x` (see `gamma1pm1`).
*
* @param x    input value
* @return     natural logarithm of factorial of `x`
*
* @example
* double out = stdlib_base_factorialln( 3.0 );
* // returns ~1.792
*/
double stdlib_base_factorialln( const double x ) {
	if ( stdlib_base_is_negative_integer( x ) ) {
		return STDLIB_CONSTANT_FLOAT64_NAN;
	}
	if ( x > -1.0 && x < 1.0 ) {
		return stdlib_base_log1p( stdlib_base_gamma1pm1( x ) );
	}
	return stdlib_base_gammaln( x + 1.0 );
}
